window.LESSON_SOURCES = {
  "L01_safe_copy.c": "/* L01 \u2014 Safe short copy with stack protector ON\n * Binary: bin/L01_safe_copy\n * Build:  cc -O0 -fstack-protector-strong -o bin/L01_safe_copy lessons/L01_safe_copy.c\n *\n * Lesson: When input fits the buffer, the canary stays intact and main returns normally.\n */\n#include \"common.h\"\n\nvoid greet(const char *name) {\n    char buf[BUF_SMALL];\n    /* Bound the copy \u2014 still easy to misuse if src is longer than BUF_SMALL-1 */\n    strncpy(buf, name, sizeof(buf) - 1);\n    buf[sizeof(buf) - 1] = '\\0';\n    printf(\"hello, %s\\n\", buf);\n}\n\nint main(int argc, char **argv) {\n    lesson_banner(\"L01\", \"safe short copy (protector ON)\");\n    if (argc < 2) {\n        fprintf(stderr, \"usage: %s <name>\\n\", argv[0]);\n        return 1;\n    }\n    greet(argv[1]);\n    puts(\"exit ok \u2014 canary untouched\");\n    return 0;\n}\n",
  "L02_strcpy_overflow.c": "/* L02 \u2014 Unbounded strcpy overflow \u2192 stack smashing detected\n * Binary: bin/L02_strcpy_overflow\n * Build:  cc -O0 -fstack-protector-strong -o bin/L02_strcpy_overflow lessons/L02_strcpy_overflow.c\n *\n * Lesson: strcpy does not know the destination size. Long input kills the canary.\n */\n#include \"common.h\"\n\nvoid copy_name(const char *src) {\n    char buf[BUF_SMALL];\n    strcpy(buf, src); /* UNSAFE: no bounds check */\n    printf(\"copied: %s\\n\", buf);\n}\n\nint main(int argc, char **argv) {\n    lesson_banner(\"L02\", \"strcpy overflow (protector ON)\");\n    if (argc < 2) {\n        fprintf(stderr, \"usage: %s <name>\\n\", argv[0]);\n        return 1;\n    }\n    copy_name(argv[1]);\n    puts(\"returned from copy_name\");\n    return 0;\n}\n",
  "L03_stack_layout.c": "/* L03 \u2014 Same overflow, annotated stack layout\n * Binary: bin/L03_stack_layout\n * Build:  cc -O0 -fstack-protector-strong -o bin/L03_stack_layout lessons/L03_stack_layout.c\n *\n * Lesson: Visualize [buffer][canary][saved RBP][return addr] growth direction.\n */\n#include \"common.h\"\n\nvoid vulnerable(const char *src) {\n    char buf[BUF_SMALL];\n    printf(\"stack sketch (low \u2192 high):\\n\");\n    printf(\"  buf[%d]  @ %p\\n\", BUF_SMALL, (void *)buf);\n    printf(\"  ...canary / saved rbp / ret above buf on many ABIs...\\n\");\n    strcpy(buf, src); /* UNSAFE */\n    printf(\"buf = %s\\n\", buf);\n}\n\nint main(int argc, char **argv) {\n    lesson_banner(\"L03\", \"stack layout under overflow\");\n    if (argc < 2) {\n        fprintf(stderr, \"usage: %s <payload>\\n\", argv[0]);\n        return 1;\n    }\n    vulnerable(argv[1]);\n    return 0;\n}\n",
  "L04_gets_banned.c": "/* L04 \u2014 gets() is banned (unbounded stdin read)\n * Binary: bin/L04_gets_banned\n * Build:  cc -O0 -fstack-protector-strong -o bin/L04_gets_banned lessons/L04_gets_banned.c\n *\n * Lesson: gets() cannot limit input length. Never use it \u2014 prefer fgets().\n * (libc no longer provides gets; this shim recreates the same unbounded hazard.)\n */\n#include \"common.h\"\n\n/* Historic gets() semantics: read until newline/EOF with NO size check. */\nstatic char *dangerous_gets(char *dst) {\n    int c;\n    char *p = dst;\n    while ((c = getchar()) != EOF && c != '\\n') {\n        *p++ = (char)c; /* UNSAFE: may run far past dst */\n    }\n    *p = '\\0';\n    return dst;\n}\n\nvoid read_line(void) {\n    char buf[BUF_SMALL];\n    printf(\"Enter name: \");\n    fflush(stdout);\n    dangerous_gets(buf); /* NEVER DO THIS \u2014 gets() was removed from C11 for a reason */\n    printf(\"got: %s\\n\", buf);\n}\n\nint main(void) {\n    lesson_banner(\"L04\", \"gets() is banned\");\n    read_line();\n    return 0;\n}\n",
  "L05_size_mismatch.c": "/* L05 \u2014 Buffer size mismatch: tiny stack buf, huge read\n * Binary: bin/L05_size_mismatch\n * Build:  cc -O0 -fstack-protector-strong -o bin/L05_size_mismatch lessons/L05_size_mismatch.c\n *\n * Lesson: Declaring char buf[8] then reading with a larger limit (or none) is a classic bug.\n */\n#include \"common.h\"\n\nvoid ingest(void) {\n    char buf[BUF_SMALL];\n    char big[64];\n    printf(\"Enter data: \");\n    fflush(stdout);\n    if (!fgets(big, sizeof(big), stdin)) {\n        return;\n    }\n    /* BUG: copies up to 63 bytes into an 8-byte buffer */\n    strcpy(buf, big);\n    printf(\"stored: %s\\n\", buf);\n}\n\nint main(void) {\n    lesson_banner(\"L05\", \"buffer size mismatch\");\n    ingest();\n    return 0;\n}\n",
  "L06_epilogue_check.c": "/* L06 \u2014 Function epilogue canary check (smash \u2192 abort)\n * Binary: bin/L06_epilogue_check\n * Build:  cc -O0 -fstack-protector-strong -o bin/L06_epilogue_check lessons/L06_epilogue_check.c\n *\n * Lesson: Before ret, the compiler emits a canary check. Mismatch \u2192 __stack_chk_fail.\n */\n#include \"common.h\"\n\n__attribute__((noinline))\nvoid worker(const char *src) {\n    char buf[BUF_SMALL];\n    strcpy(buf, src);\n    printf(\"work done on '%s'\\n\", buf);\n    /* epilogue here: compare canary, else call __stack_chk_fail */\n}\n\nint main(int argc, char **argv) {\n    lesson_banner(\"L06\", \"epilogue canary check\");\n    if (argc < 2) {\n        fprintf(stderr, \"usage: %s <payload>\\n\", argv[0]);\n        return 1;\n    }\n    worker(argv[1]);\n    puts(\"back in main \u2014 only if canary matched\");\n    return 0;\n}\n",
  "L07_guard_off.c": "/* L07 \u2014 Stack protector DISABLED (\u2212fno-stack-protector)\n * Binary: bin/L07_guard_off\n * Build:  cc -O0 -fno-stack-protector -o bin/L07_guard_off lessons/L07_guard_off.c\n *\n * Lesson: Same overflow with no bird. Return address can be corrupted silently.\n */\n#include \"common.h\"\n\nvoid open_gate(const char *src) {\n    char buf[BUF_SMALL];\n    strcpy(buf, src); /* UNSAFE, and no canary */\n    printf(\"gate opened for %s\\n\", buf);\n}\n\nint main(int argc, char **argv) {\n    lesson_banner(\"L07\", \"guard OFF (-fno-stack-protector)\");\n    if (argc < 2) {\n        fprintf(stderr, \"usage: %s <payload>\\n\", argv[0]);\n        return 1;\n    }\n    open_gate(argv[1]);\n    puts(\"returned \u2014 if RET was smashed, we may never get here cleanly\");\n    return 0;\n}\n",
  "L08_off_by_one.c": "/* L08 \u2014 Off-by-one: write one byte past the end\n * Binary: bin/L08_off_by_one\n * Build:  cc -O0 -fstack-protector-strong -o bin/L08_off_by_one lessons/L08_off_by_one.c\n *\n * Lesson: Loops using <= length or writing the NUL past the last index corrupt neighbors\n * (often the canary's low byte on some layouts).\n */\n#include \"common.h\"\n\nvoid fill(const char *src) {\n    char buf[BUF_SMALL];\n    size_t n = strlen(src);\n    size_t i;\n    /* BUG: uses <= so one extra byte is written when n == BUF_SMALL */\n    for (i = 0; i <= n && i <= BUF_SMALL; i++) {\n        buf[i] = src[i];\n    }\n    printf(\"filled %zu bytes (buggy bound)\\n\", n);\n}\n\nint main(int argc, char **argv) {\n    lesson_banner(\"L08\", \"off-by-one write\");\n    if (argc < 2) {\n        fprintf(stderr, \"usage: %s <exactly-8-chars-ideal>\\n\", argv[0]);\n        return 1;\n    }\n    fill(argv[1]);\n    return 0;\n}\n",
  "L09_strncpy_pitfall.c": "/* L09 \u2014 strncpy without forced NUL termination\n * Binary: bin/L09_strncpy_pitfall\n * Build:  cc -O0 -fstack-protector-strong -o bin/L09_strncpy_pitfall lessons/L09_strncpy_pitfall.c\n *\n * Lesson: strncpy may omit the terminating NUL when src length >= n.\n * Always set buf[n-1] = '\\\\0' (or use safer APIs).\n */\n#include \"common.h\"\n\nvoid bad_copy(const char *src) {\n    char buf[BUF_SMALL];\n    strncpy(buf, src, sizeof(buf)); /* if src >= 8, buf has NO NUL */\n    /* BUG: printf walks past buf looking for '\\\\0' \u2014 memory safety hazard */\n    printf(\"buf prints as: %s\\n\", buf);\n}\n\nint main(int argc, char **argv) {\n    lesson_banner(\"L09\", \"strncpy NUL pitfall\");\n    if (argc < 2) {\n        fprintf(stderr, \"usage: %s <string-of-len-8+>\\n\", argv[0]);\n        return 1;\n    }\n    bad_copy(argv[1]);\n    return 0;\n}\n",
  "L10_libcanary.c": "/* L10 \u2014 Manual canary with libcanary (derived secret \u2295 frame)\n * Binary: bin/L10_libcanary\n * Build:  see Makefile (links libcanary/canary.c)\n *\n * Lesson: Plant a derived canary, check before return \u2014 mirrors compiler SSP.\n */\n#include \"common.h\"\n#include \"../libcanary/canary.h\"\n\nvoid guarded(const char *src) {\n    char buf[BUF_SMALL];\n    uint64_t canary_slot;\n    void *frame = __builtin_frame_address(0);\n    void *ret = __builtin_return_address(0);\n\n    canary_slot = canary_deriv(frame, ret, &canary_slot);\n\n    strncpy(buf, src, sizeof(buf) - 1);\n    buf[sizeof(buf) - 1] = '\\0';\n    printf(\"libcanary greet: %s\\n\", buf);\n\n    if (canary_check(frame, ret, &canary_slot) != 0) {\n        canary_fail();\n    }\n}\n\nint main(int argc, char **argv) {\n    lesson_banner(\"L10\", \"libcanary derived canary\");\n    canary_init();\n    if (argc < 2) {\n        fprintf(stderr, \"usage: %s <name>\\n\", argv[0]);\n        return 1;\n    }\n    guarded(argv[1]);\n    puts(\"libcanary check passed\");\n    return 0;\n}\n",
  "L11_safe_fgets.c": "/* L11 \u2014 Safe rewrite: fgets + snprintf (no unbounded copy)\n * Binary: bin/L11_safe_fgets\n * Build:  cc -O0 -fstack-protector-strong -o bin/L11_safe_fgets lessons/L11_safe_fgets.c\n *\n * Lesson: Bound every read and every format. This is the pattern to ship.\n */\n#include \"common.h\"\n\nvoid safe_greet(void) {\n    char name[BUF_MED];\n    char out[64];\n\n    printf(\"Enter name: \");\n    fflush(stdout);\n    if (!fgets(name, sizeof(name), stdin)) {\n        return;\n    }\n    /* strip newline */\n    name[strcspn(name, \"\\n\")] = '\\0';\n\n    snprintf(out, sizeof(out), \"hello, %s\", name);\n    puts(out);\n}\n\nint main(void) {\n    lesson_banner(\"L11\", \"safe fgets + snprintf\");\n    safe_greet();\n    puts(\"clean return \u2014 defender pattern\");\n    return 0;\n}\n",
  "L12_hardening.c": "/* L12 \u2014 Hardening checklist binary (protector + fortified libc)\n * Binary: bin/L12_hardening\n * Build:  cc -O2 -fstack-protector-strong -D_FORTIFY_SOURCE=2 \\\n *            -o bin/L12_hardening lessons/L12_hardening.c\n *\n * Lesson: Defense in depth \u2014 canaries + fortified unchecked copies + safe APIs.\n */\n#include \"common.h\"\n\nvoid harden_demo(const char *src) {\n    char buf[BUF_MED];\n    /* With _FORTIFY_SOURCE, oversized constant copies can be caught at compile/runtime */\n    snprintf(buf, sizeof(buf), \"%s\", src);\n    printf(\"hardened echo: %s\\n\", buf);\n}\n\nint main(int argc, char **argv) {\n    lesson_banner(\"L12\", \"hardening checklist\");\n    puts(\"checklist:\");\n    puts(\"  [x] -fstack-protector-strong\");\n    puts(\"  [x] -D_FORTIFY_SOURCE=2\");\n    puts(\"  [x] fgets/snprintf instead of gets/strcpy\");\n    puts(\"  [x] never disable canaries in production\");\n    if (argc < 2) {\n        fprintf(stderr, \"usage: %s <short-name>\\n\", argv[0]);\n        return 1;\n    }\n    harden_demo(argv[1]);\n    puts(\"mission complete\");\n    return 0;\n}\n",
  "common.h": "#ifndef LESSON_COMMON_H\n#define LESSON_COMMON_H\n\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <unistd.h>\n\n#define BUF_SMALL 8\n#define BUF_MED   16\n\nstatic inline void lesson_banner(const char *id, const char *title) {\n    fprintf(stderr, \"[%s] %s\\n\", id, title);\n}\n\n#endif\n",
  "canary.h": "/*\n * libcanary \u2014 a small, real stack-canary library for hardening C/C++ code\n * against stack-buffer-overflow memory corruption.\n *\n * This is a *teaching* library: every line is meant to be read by students\n * learning how a stack canary (a.k.a. stack cookie / stack-smashing protector)\n * actually works under the hood. It is deliberately simple, but it is also a\n * genuine, working mitigation you can drop into a function to detect that a\n * buffer overflow has clobbered the bytes guarding your return address or a\n * sensitive local.\n *\n * It gives you two complementary tools:\n *\n *   1. A classic *frame canary* (LC_GUARD / LC_VERIFY). A random value is\n *      planted on the stack at function entry and re-checked before return \u2014\n *      exactly the technique GCC/Clang emit for -fstack-protector. Use it to\n *      understand how the compiler's protector works and to protect a function\n *      the compiler is NOT instrumenting.\n *\n *   2. A deterministic *guarded buffer* (LC_GUARDED / lc_buf_check). A random\n *      guard word is placed in memory immediately after a fixed-size buffer.\n *      Any linear overflow that runs off the end of the buffer must trample the\n *      guard before it can reach anything beyond it, so corruption is caught\n *      reliably and independently of how the compiler happened to lay out the\n *      stack. This is what the before/after demo uses.\n *\n * SPDX-License-Identifier: MIT\n */\n#ifndef LIBCANARY_H\n#define LIBCANARY_H\n\n#include <stddef.h>\n#include <stdint.h>\n\n#ifdef __cplusplus\nextern \"C\" {\n#endif\n\n/* ----------------------------------------------------------------------------\n * Core runtime\n * ------------------------------------------------------------------------- */\n\n/*\n * Generate the per-process canary secret.\n *\n * Called automatically before main() via a constructor, so you normally never\n * need to call it yourself. It is idempotent and thread-safe, so calling it\n * again is harmless. The secret is drawn from the OS CSPRNG (getrandom(2),\n * falling back to /dev/urandom, falling back to an ASLR-seeded mix) and then\n * masked so its least-significant byte is 0x00. The null byte is deliberate:\n * it stops string functions like strcpy/strcat \u2014 which stop at a NUL \u2014 from\n * leaking or faithfully reproducing the canary. This mirrors glibc's canary.\n */\nvoid lc_init(void);\n\n/*\n * Return the current per-process canary value. Every guard is armed with this\n * value and every check compares against it. Cheap after the first call.\n */\nuint64_t lc_canary_value(void);\n\n/*\n * Report that a canary was found corrupted and terminate the process safely.\n *\n * \"Safely\" means: we do NOT return into a frame whose return address may have\n * been overwritten, and we do NOT run normal cleanup that an attacker might\n * have corrupted. We print a one-line diagnostic to stderr and raise SIGABRT\n * via abort(), which is the same fail-closed behaviour as __stack_chk_fail.\n *\n * `where` is a short label (typically the function name) included in the\n * message. This function never returns.\n */\nvoid lc_report_and_abort(const char *where) __attribute__((noreturn));\n\n/* ----------------------------------------------------------------------------\n * Tool 1 \u2014 classic frame canary (the textbook stack cookie)\n *\n *   void risky(const char *in) {\n *       LC_GUARD;                 // plant the cookie at function entry\n *       char name[32];\n *       strncpy(name, in, sizeof name - 1);\n *       ...\n *       LC_VERIFY();              // check it right before every return\n *   }\n *\n * Declare LC_GUARD as the FIRST local in the function so the compiler is free\n * to place the cookie between your buffers and the saved return address, and\n * build the function with -fno-stack-protector if you want this to be the only\n * canary present (otherwise the compiler's own protector also runs \u2014 which is\n * perfectly fine, and the point of lesson L06).\n * ------------------------------------------------------------------------- */\n\n#define LC_GUARD      volatile uint64_t __lc_cookie = lc_canary_value()\n#define LC_VERIFY()                                                            \\\n    do {                                                                       \\\n        if (__lc_cookie != lc_canary_value())                                  \\\n            lc_report_and_abort(__func__);                                     \\\n    } while (0)\n\n/* ----------------------------------------------------------------------------\n * Tool 2 \u2014 deterministic guarded buffer (a redzone canary)\n *\n *   void handle(const char *in) {\n *       LC_GUARDED(name, 32);                 // 32-byte buffer + trailing guard\n *       strcpy((char *)name.data, in);        // untrusted copy into name.data\n *       lc_buf_check(&name);                   // aborts if the guard was hit\n *       puts((char *)name.data);\n *   }\n *\n * The guard word lives in memory immediately after the buffer, so a linear\n * overflow past name.data clobbers it before reaching anything else. This\n * catches the classic unbounded-strcpy overflow every time, regardless of the\n * compiler's stack layout \u2014 which is why the demo uses it.\n * ------------------------------------------------------------------------- */\n\ntypedef struct lc_buf {\n    unsigned char *data;  /* start of the writable region       */\n    size_t         size;  /* capacity of data, in bytes         */\n    uint64_t      *guard; /* guard word, sits right after data  */\n} lc_buf;\n\n/* Declare a guarded buffer `name` of `n` bytes and arm its guard. */\n#define LC_GUARDED(name, n)                                                    \\\n    struct {                                                                   \\\n        unsigned char __d[(n)];                                                \\\n        uint64_t      __g;                                                     \\\n    } name##__box;                                                             \\\n    name##__box.__g = lc_canary_value();                                       \\\n    lc_buf name = { name##__box.__d, (size_t)(n), &name##__box.__g }\n\n/* Return 1 if the guard is intact, 0 if it was overwritten. */\nint  lc_buf_ok(const lc_buf *b);\n\n/* Abort because this buffer's guard was corrupted. Never returns. */\nvoid lc_buf_fail(const lc_buf *b) __attribute__((noreturn));\n\n/* Convenience: verify and, on corruption, report + abort. */\nvoid lc_buf_check(const lc_buf *b);\n\n/* ----------------------------------------------------------------------------\n * Legacy derived-canary API (kept so lesson L10 keeps building).\n *\n * These implement a canary *derived* from the frame and return address XORed\n * with the secret, so the planted value differs per call site. canary_check\n * returns 0 when intact and non-zero when corrupted.\n * ------------------------------------------------------------------------- */\nvoid     canary_init(void);\nuint64_t canary_deriv(void *frame_addr, void *ret_addr, void *store_addr);\nuint64_t canary_check(void *frame_addr, void *ret_addr, void *store_addr);\nvoid     canary_fail(void) __attribute__((noreturn));\n\n#ifdef __cplusplus\n} /* extern \"C\" */\n#endif\n\n#endif /* LIBCANARY_H */\n",
  "canary.c": "/*\n * libcanary \u2014 implementation.\n *\n * Read this top to bottom: it is the whole mitigation in one short file.\n * A stack canary is nothing more than \"plant a secret random value in front\n * of the thing you want to protect, then check the value is still there before\n * you trust that thing.\" Everything below is bookkeeping around that idea.\n *\n * SPDX-License-Identifier: MIT\n */\n#include \"canary.h\"\n\n#include <fcntl.h>\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <time.h>\n#include <unistd.h>\n\n#if defined(__linux__)\n#include <sys/random.h> /* getrandom() */\n#endif\n\n/* ----------------------------------------------------------------------------\n * The per-process secret\n * ------------------------------------------------------------------------- */\n\nstatic uint64_t g_secret;      /* the canary value, chosen once per process  */\nstatic int      g_initialised; /* 0 until lc_init() has run                   */\n\n/*\n * Fill `out` with `len` cryptographically-random bytes. Returns 1 on success.\n * We try, in order: getrandom(2), then /dev/urandom. Callers must handle the\n * 0 return by mixing in a weaker fallback (see lc_init).\n */\nstatic int fill_random(void *out, size_t len)\n{\n#if defined(__linux__)\n    /* getrandom() with no flags blocks only until the pool is seeded, which\n     * has already happened long before any normal program runs. */\n    ssize_t got = getrandom(out, len, 0);\n    if (got == (ssize_t)len)\n        return 1;\n#endif\n    int fd = open(\"/dev/urandom\", O_RDONLY | O_CLOEXEC);\n    if (fd >= 0) {\n        size_t off = 0;\n        while (off < len) {\n            ssize_t r = read(fd, (unsigned char *)out + off, len - off);\n            if (r <= 0)\n                break;\n            off += (size_t)r;\n        }\n        close(fd);\n        if (off == len)\n            return 1;\n    }\n    return 0;\n}\n\nvoid lc_init(void)\n{\n    if (g_initialised)\n        return;\n\n    uint64_t secret = 0;\n    if (!fill_random(&secret, sizeof secret)) {\n        /* Last-resort fallback for exotic environments with no CSPRNG: mix\n         * several hard-to-predict runtime values. This is weaker than a real\n         * CSPRNG \u2014 but we only reach it if both getrandom() and /dev/urandom\n         * failed, which essentially never happens on a normal system. */\n        struct timespec ts = {0, 0};\n        clock_gettime(CLOCK_MONOTONIC, &ts);\n        secret ^= (uint64_t)ts.tv_nsec;\n        secret ^= (uint64_t)ts.tv_sec * 0x9E3779B97F4A7C15ULL;\n        secret ^= (uint64_t)(uintptr_t)&secret;      /* a stack address (ASLR) */\n        secret ^= (uint64_t)(uintptr_t)&lc_init << 1; /* a code address (ASLR) */\n        secret ^= (uint64_t)getpid() * 0xD1B54A32D192ED03ULL;\n    }\n\n    /* Force the least-significant byte to 0x00 (a \"terminator canary\"). String\n     * routines stop at the first NUL, so an attacker overflowing with a C\n     * string cannot write a value whose low byte matches, and cannot copy the\n     * canary out through a string read. glibc's canary uses the same trick. */\n    secret &= ~(uint64_t)0xFF;\n\n    g_secret = secret;\n    g_initialised = 1;\n}\n\n/* Run lc_init() automatically before main(), so guards planted in any\n * function already have a live secret to use. */\n__attribute__((constructor))\nstatic void lc_autoinit(void)\n{\n    lc_init();\n}\n\nuint64_t lc_canary_value(void)\n{\n    if (!g_initialised)\n        lc_init();\n    return g_secret;\n}\n\n/* ----------------------------------------------------------------------------\n * Failing closed\n * ------------------------------------------------------------------------- */\n\nvoid lc_report_and_abort(const char *where)\n{\n    /* Use low-level write() rather than fprintf: the heap and stdio buffers\n     * may already be corrupted by the overflow we just detected. */\n    const char prefix[] = \"*** libcanary: stack corruption detected in \";\n    const char suffix[] = \"() \u2014 aborting ***\\n\";\n    /* (void)! swallows write()'s warn_unused_result attribute: there is\n     * nothing sensible to do if the diagnostic itself fails to print. */\n    (void)!write(STDERR_FILENO, prefix, sizeof prefix - 1);\n    if (where)\n        (void)!write(STDERR_FILENO, where, strlen(where));\n    (void)!write(STDERR_FILENO, suffix, sizeof suffix - 1);\n\n    /* Fail closed: never return into a frame whose return address may be\n     * attacker-controlled. abort() raises SIGABRT and does not come back. */\n    abort();\n}\n\n/* ----------------------------------------------------------------------------\n * Guarded buffer (redzone canary)\n * ------------------------------------------------------------------------- */\n\nint lc_buf_ok(const lc_buf *b)\n{\n    return b && b->guard && *b->guard == lc_canary_value();\n}\n\nvoid lc_buf_fail(const lc_buf *b)\n{\n    (void)b;\n    lc_report_and_abort(\"guarded buffer\");\n}\n\nvoid lc_buf_check(const lc_buf *b)\n{\n    if (!lc_buf_ok(b))\n        lc_buf_fail(b);\n}\n\n/* ----------------------------------------------------------------------------\n * Legacy derived-canary API (lesson L10)\n *\n * A canary derived per call site: XOR the secret with the frame and return\n * addresses so the planted value is unique to where it was planted.\n * ------------------------------------------------------------------------- */\n\nvoid canary_init(void)\n{\n    lc_init();\n}\n\nuint64_t canary_deriv(void *frame_addr, void *ret_addr, void *store_addr)\n{\n    (void)store_addr;\n    uint64_t canary = lc_canary_value();\n    canary ^= (uint64_t)(uintptr_t)ret_addr;\n    canary ^= ((uint64_t)(uintptr_t)frame_addr * 0xdeadbeefcafebabeULL);\n    return canary;\n}\n\nuint64_t canary_check(void *frame_addr, void *ret_addr, void *store_addr)\n{\n    uint64_t expected = canary_deriv(frame_addr, ret_addr, store_addr);\n    uint64_t stored = 0;\n    memcpy(&stored, store_addr, sizeof stored);\n    return expected ^ stored; /* 0 == intact */\n}\n\nvoid canary_fail(void)\n{\n    lc_report_and_abort(\"L10 derived canary\");\n}\n"
};
